window.СБОРКА = (function () {
'use strict';
const НАСТРОЙКИ = window.СБОРКА_НАСТРОЙКИ;
const МИР       = window.СБОРКА_ДАННЫЕ;
const { БРАНЬ } = window.СБОРКА_БРАНЬ;
const $ = (ид) => document.getElementById(ид);
let выбор = null;
let герой = null;
let шаг = 0;
let поломка = false;
function применитьОттенок(ключНарода) {
  document.documentElement.style.setProperty(
    '--оттенок', МИР.народы[ключНарода].оттенок);
}
function расставитьТексты() {
  document.querySelectorAll('[data-т]').forEach((узел) => {
    const слово = МИР.тексты[узел.dataset.т];
    if (слово !== undefined) узел.textContent = слово;
  });
}
const случайное = (сколько) => Math.floor(Math.random() * сколько);
const ключиНародов = () => Object.keys(МИР.народы);
function знакНарода(ключ, размер) {
  const н = МИР.народы[ключ];
  return '<svg xmlns="' + НАСТРОЙКИ.знак.пространствоИмён +
    '" width="' + размер + '" height="' + размер +
    '" viewBox="' + НАСТРОЙКИ.знак.холст + '" fill="none" stroke="' + н.оттенок +
    '" stroke-width="' + НАСТРОЙКИ.знак.толщинаЛинии +
    '" stroke-linejoin="round">' + н.знак + '</svg>';
}
function вставитьЗнак(узел, ключ) {
  const сторона = Math.round(узел.clientWidth * НАСТРОЙКИ.знак.доля)
    || НАСТРОЙКИ.знак.поУмолчанию;
  узел.innerHTML = знакНарода(ключ, сторона);
}
const ЭКРАНЫ = ['э-вступление', 'э-конструктор', 'э-герой'];
function показатьЭкран(ид) {
  ЭКРАНЫ.forEach((э) => { $(э).hidden = (э !== ид); });
  window.scrollTo(0, 0);
}
function показатьШаг(номер) {
  шаг = номер;
  for (let i = 1; i <= НАСТРОЙКИ.шагов; i++) $('шаг-' + i).hidden = (i !== номер);
  Array.from($('полоска').children).forEach((и, i) => {
    и.classList.toggle('есть', i < номер);
  });
  window.scrollTo(0, 0);
}
function случайныйВыбор() {
  const народ = ключиНародов()[случайное(ключиНародов().length)];
  const н = МИР.народы[народ];
  return {
    народ: народ,
    пол: МИР.полы[случайное(МИР.полы.length)].ключ,
    телосложение: МИР.телосложения[случайное(МИР.телосложения.length)].ключ,
    цвет: н.цвета[случайное(н.цвета.length)].имя,
    отметина: МИР.отметины[случайное(МИР.отметины.length)].ключ,
    имя: '',
    девиз: н.девизы[случайное(н.девизы.length)].ключ,
    плащ: МИР.плащи[случайное(МИР.плащи.length)].имя,
    зерно: случайное(НАСТРОЙКИ.зерно.предел)
  };
}
function случайноеИмя(ключНарода) {
  const слоги = МИР.народы[ключНарода].слоги;
  return слоги[случайное(слоги.length)] +
         слоги[случайное(слоги.length)].toLowerCase();
}
function нарисоватьНароды() {
  $('народы').innerHTML = ключиНародов().map((к) => {
    const н = МИР.народы[к];
    return '<div class="народ' + (к === выбор.народ ? ' выбран' : '') +
      '" data-народ="' + к + '" style="border-color:' +
      (к === выбор.народ ? н.оттенок : 'transparent') + '">' +
      '<div class="знак" style="border-color:' + н.оттенок + '">' +
      знакНарода(к, НАСТРОЙКИ.знак.поУмолчанию) + '</div>' +
      '<div><b>' + н.имя + '</b><span>' + н.о + '</span></div></div>';
  }).join('');
}
function нарисоватьОблик() {
  const н = МИР.народы[выбор.народ];
  $('полы').innerHTML = МИР.полы.map((п) =>
    '<div class="вар' + (п.ключ === выбор.пол ? ' выбран' : '') +
    '" data-пол="' + п.ключ + '">' + п.имя + '</div>').join('');
  $('телосложения').innerHTML = МИР.телосложения.map((т) =>
    '<div class="вар' + (т.ключ === выбор.телосложение ? ' выбран' : '') +
    '" data-телосложение="' + т.ключ + '">' + т.имя + '</div>').join('');
  $('цвета').innerHTML = н.цвета.map((ц) =>
    '<div class="цвет' + (ц.имя === выбор.цвет ? ' выбран' : '') +
    '" style="background:' + ц.код + '" title="' + ц.имя +
    '" data-цвет="' + ц.имя + '"></div>').join('');
  $('отметины').innerHTML = МИР.отметины.map((о) =>
    '<div class="вар' + (о.ключ === выбор.отметина ? ' выбран' : '') +
    '" data-отметина="' + о.ключ + '">' + о.имя + '</div>').join('');
}
function обновитьПревью() {
  const н = МИР.народы[выбор.народ];
  const т = МИР.телосложения.find((э) => э.ключ === выбор.телосложение);
  const о = МИР.отметины.find((э) => э.ключ === выбор.отметина);
  const подпись = подставить(МИР.шаблоны.облик, {
    народ: н.имя.toLowerCase(), телосложение: т.имя,
    цвет: выбор.цвет, отметина: о.имя
  });
  применитьОттенок(выбор.народ);
  ['знак-превью', 'знак-сводка'].forEach((ид) => вставитьЗнак($(ид), выбор.народ));
  $('имя-превью').textContent = выбор.имя || МИР.тексты.безымянный;
  $('имя-сводка').textContent = выбор.имя || МИР.тексты.безымянный;
  $('облик-превью').textContent = подпись;
  $('облик-сводка').textContent = подпись;
}
function перерисоватьВсё() {
  нарисоватьНароды();
  нарисоватьОблик();
  обновитьПревью();
}
function выбратьНарод(ключ) {
  if (ключ === выбор.народ) return;
  выбор.народ = ключ;
  выбор.цвет = МИР.народы[ключ].цвета[0].имя;
  const девизы = МИР.народы[ключ].девизы;
  выбор.девиз = девизы[случайное(девизы.length)].ключ;
  перерисоватьВсё();
}
function перемешать() {
  const было = выбор.имя;
  выбор = случайныйВыбор();
  выбор.имя = было || случайноеИмя(выбор.народ);
  $('поле-имя').value = выбор.имя;
  перерисоватьВсё();
  проверитьИмя();
}
function ошибкаИмени(значение) {
  const п = НАСТРОЙКИ.имя;
  const т = МИР.тексты;
  if (!значение.length) return '';
  if (значение.length < п.мин) return т.ошибка_коротко;
  if (значение.length > п.макс) return т.ошибка_длинно;
  if (new RegExp(п.цифры).test(значение)) return т.ошибка_цифры;
  if (new RegExp(п.разрешённыеЗнаки).test(значение)) return т.ошибка_знаки;
  if (new RegExp(п.дваПробела).test(значение)) return т.ошибка_пробелы;
  const строчными = значение.toLowerCase();
  if (БРАНЬ.some((слово) => строчными.includes(слово))) return т.ошибка_брань;
  return '';
}
function проверитьИмя() {
  const значение = $('поле-имя').value.trim();
  выбор.имя = значение;
  const ошибка = ошибкаИмени(значение);
  $('ошибка-имени').textContent = ошибка;
  $('к-имя-дальше').disabled = !(значение.length >= НАСТРОЙКИ.имя.мин && !ошибка);
  обновитьПревью();
}
function подставить(шаблон, значения) {
  return шаблон.replace(/\{([^{}]+)\}/g, (всё, ключ) =>
    (ключ in значения) ? значения[ключ] : всё);
}
function строкаСудьбы(з) {
  const н = МИР.народы[з.народ];
  return подставить(МИР.судьба, {
    народ: н.имя,
    земля: н.земля,
    телосложение: МИР.телосложения.find((э) => э.ключ === з.телосложение).вФразе,
    отметина: МИР.отметины.find((э) => э.ключ === з.отметина).вФразе
  });
}
function описаниеПортрета(з) {
  const н = МИР.народы[з.народ];
  const части = {
    пол: МИР.полы.find((э) => э.ключ === з.пол).англ,
    одежда: н.одеждаАнгл,
    народ: н.англ,
    волосы: н.волосыАнгл,
    цвет: н.цвета.find((э) => э.имя === з.цвет).англ,
    телосложение: МИР.телосложения.find((э) => э.ключ === з.телосложение).англ,
    отметина: МИР.отметины.find((э) => э.ключ === з.отметина).англ
  };
  const куски = [
    подставить(МИР.описаниеПортрета, части),
    НАСТРОЙКИ.портрет.каркас
  ];
  return куски.filter(Boolean).join(', ')
    .replace(/,\s*,/g, ',').replace(/\s+/g, ' ').trim();
}
function запретДля(з) {
  const н = МИР.народы[з.народ];
  return [НАСТРОЙКИ.портрет.хвост, н && н.нельзя].filter(Boolean).join(', ');
}
function меткаУстройства() {
  const х = НАСТРОЙКИ.хранение;
  try {
    let метка = localStorage.getItem(х.ключУстройства);
    if (!метка) {
      метка = crypto.randomUUID();
      localStorage.setItem(х.ключУстройства, метка);
    }
    return метка;
  } catch (е) {
    return меткаУстройства.разовая ||
      (меткаУстройства.разовая = crypto.randomUUID());
  }
}
function изБайт(кусок) {
  return new Promise((готово, беда) => {
    const адрес = URL.createObjectURL(кусок);
    const кадр = new Image();
    кадр.onload  = () => { URL.revokeObjectURL(адрес); готово(кадр); };
    кадр.onerror = () => { URL.revokeObjectURL(адрес); беда(new Error()); };
    кадр.src = адрес;
  });
}
function вписать(кадр, окно) {
  const вид = НАСТРОЙКИ.портрет.картинка.вид;
  const доля = Math.max(окно.ширина / кадр.naturalWidth,
                        окно.высота / кадр.naturalHeight);
  const ш = кадр.naturalWidth * доля, в = кадр.naturalHeight * доля;
  const холст = document.createElement('canvas');
  холст.width = окно.ширина;
  холст.height = окно.высота;
  холст.getContext('2d').drawImage(кадр, (окно.ширина - ш) / 2, (окно.высота - в) / 2, ш, в);
  return холст.toDataURL(вид, окно.качество);
}
async function разобрать(кусок) {
  const кадр = await изБайт(кусок);
  return { фигура: вписать(кадр, НАСТРОЙКИ.портрет.картинка.фигура) };
}
const ИСТОЧНИКИ = {
  посредник: {
    ходок: (з, сторож) => уПосредника(з, сторож),
    готов: () => Boolean(НАСТРОЙКИ.портрет.адрес)
  },
  pollinations: {
    ходок: (з, сторож) => уВремянки(з, сторож),
    готов: () => Boolean(НАСТРОЙКИ.портрет.времянка.адрес)
  }
};
function генерацияЕсть() {
  const и = ИСТОЧНИКИ[НАСТРОЙКИ.портрет.источник];
  return Boolean(и) && и.готов();
}
function уПосредника(з, сторож) {
  const п = НАСТРОЙКИ.портрет;
  return fetch(п.адрес + '?' + new URLSearchParams({ дело: п.дело }), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      описание: описаниеПортрета(з),
      запрет: запретДля(з),
      ширина: п.ширина,
      высота: п.высота,
      зерно: з.зерно,
      устройство: меткаУстройства()
    }),
    signal: сторож
  });
}
function уВремянки(з, сторож) {
  const п = НАСТРОЙКИ.портрет;
  return fetch(п.времянка.адрес + encodeURIComponent(описаниеПортрета(з)) + '?' +
    new URLSearchParams({
      width: п.ширина, height: п.высота, seed: з.зерно,
      nologo: 'true', private: 'true', negative_prompt: запретДля(з)
    }), { signal: сторож });
}
async function получитьПортрет(з) {
  const п = НАСТРОЙКИ.портрет;
  if (!генерацияЕсть()) return { беда: п.коды.нетПосредника };
  const сторож = new AbortController();
  const будильник = setTimeout(() => сторож.abort(), п.ожиданиеМс);
  try {
    const ответ = await ИСТОЧНИКИ[п.источник].ходок(з, сторож.signal);
    if (!ответ.ok) {
      const сказано = await ответ.json().catch(() => null);
      return { беда: (сказано && сказано.беда) || п.коды.отказ };
    }
    const своя = await разобрать(await ответ.blob());
    return { ...своя, источник: п.источник };
  } catch (е) {
    return { беда: п.коды.отказ };
  } finally {
    clearTimeout(будильник);
  }
}
function ключФигуры(з) {
  return НАСТРОЙКИ.портрет.библиотека.ключи
    .map((к) => String(з[к]).replace(/\s+/g, '-')).join('_');
}
function путиНастоящих(з) {
  const н = НАСТРОЙКИ.портрет.библиотека.настоящие;
  const б = НАСТРОЙКИ.портрет.библиотека;
  const есть = н.есть[з.народ];
  if (!есть) return [];
  const полы = Object.keys(есть).sort((а, б) => (б === з.пол) - (а === з.пол));
  const пути = [];
  for (const пол of полы) {
    const сколько = есть[пол];
    const первый = Math.abs(з.зерно || 0) % сколько;
    for (let и = 0; и < сколько; и++) {
      const номер = ((первый + и) % сколько) + 1;
      пути.push(н.папка + з.народ + '-' + пол +
                (номер > 1 ? '-' + номер : '') + б.вид);
    }
  }
  return пути;
}
function путиФигуры(з) {
  const б = НАСТРОЙКИ.портрет.библиотека;
  const адрес = (к) => б.фигуры + к + б.вид;
  const точный = ключФигуры(з);
  const ближний = ключФигуры(Object.assign({}, з, б.ближний));
  const изБиблиотеки = !б.собрана ? []
    : точный === ближний ? [адрес(точный)]
    : [адрес(точный), адрес(ближний)];
  return изБиблиотеки.concat(путиНастоящих(з));
}
function показатьПортрет(з) {
  const место = $('портрет');
  место.innerHTML = '';
  const кадр = new Image();
  кадр.alt = '';
  const пути = з.портрет ? [з.портрет] : путиФигуры(з);
  let который = 0;
  кадр.onerror = () => {
    который += 1;
    if (который < пути.length) { кадр.src = пути[который]; return; }
    место.innerHTML = '<div class="знак">' +
      знакНарода(з.народ, Math.round(место.clientHeight * НАСТРОЙКИ.знак.доля)) + '</div>';
  };
  кадр.src = пути[0];
  место.appendChild(кадр);
  $('к-портрет').hidden = попыткиКончились(з);
}
function попыткиКончились(з) {
  return (з.попыток || 0) >= НАСТРОЙКИ.портрет.попытокПредел;
}
async function догнатьПортрет() {
  if (попыткиКончились(герой)) return;
  $('к-портрет').disabled = true;
  $('портрет').innerHTML = '<div class="ждём">' + МИР.тексты.портрет_ждём + '</div>';
  герой.зерно = случайное(НАСТРОЙКИ.зерно.предел);
  try {
    const вышло = await получитьПортрет(герой);
    if (положитьПортрет(герой, вышло)) герой.попыток = (герой.попыток || 0) + 1;
    сообщитьОПортрете(герой, вышло.беда);
    сохранить(герой);
  } finally {
    показатьПортрет(герой);
    $('к-портрет').disabled = false;
  }
}
async function обновитьСтарыйПортрет() {
  if (!герой || !герой.портретСтарый || !генерацияЕсть()) return;
  const вышло = await получитьПортрет(герой);
  if (!положитьПортрет(герой, вышло)) return;
  сохранить(герой);
  показатьПортрет(герой);
}
function сообщитьОПортрете(з, беда) {
  const т = МИР.тексты;
  if (з.портрет && !беда) {
    $('сообщение').textContent = попыткиКончились(з) ? т.портрет_попытки : '';
    return;
  }
  $('сообщение').textContent =
    т[НАСТРОЙКИ.портрет.коды.приставка + беда] || т.портрет_нет;
}
function цветКожи(з) {
  const цвета = МИР.народы[з.народ].цвета;
  return (цвета.find((ц) => ц.имя === з.цвет) || цвета[0]).код;
}
function цветПлаща(з) {
  return (МИР.плащи.find((п) => п.имя === з.плащ) || МИР.плащи[0]).код;
}
function сохранить(запись) {
  try {
    localStorage.setItem(НАСТРОЙКИ.хранение.ключ, JSON.stringify(запись));
    return true;
  } catch (е) {
    return false;
  }
}
function достать() {
  let строка;
  try {
    строка = localStorage.getItem(НАСТРОЙКИ.хранение.ключ);
  } catch (е) {
    return { пусто: true };
  }
  if (!строка) return { пусто: true };
  try {
    const запись = JSON.parse(строка);
    if (!запись || !МИР.народы[запись.народ]) return { поломка: true };
    const переведена = перевести(запись);
    if (!записьЦела(переведена)) return { поломка: true };
    снабдитьЛицом(переведена);
    сохранить(переведена);
    return { запись: переведена };
  } catch (е) {
    return { поломка: true };
  }
}
function записьЦела(з) {
  if (!з || typeof з !== 'object') return false;
  if (typeof з.имя !== 'string') return false;
  з.имя = з.имя.trim();
  if (з.имя.length < НАСТРОЙКИ.имя.мин) return false;
  if (з.имя.length > НАСТРОЙКИ.имя.макс) return false;
  if (ошибкаИмени(з.имя)) return false;
  const н = МИР.народы[з.народ];
  if (!н) return false;
  if (!МИР.полы.some((п) => п.ключ === з.пол)) return false;
  if (!МИР.телосложения.some((т) => т.ключ === з.телосложение)) return false;
  if (!МИР.отметины.some((о) => о.ключ === з.отметина)) return false;
  if (!н.цвета.some((ц) => ц.имя === з.цвет)) return false;
  if (!МИР.плащи.some((п) => п.имя === з.плащ)) return false;
  if (!н.девизы.some((д) => д.ключ === з.девиз)) return false;
  const п = НАСТРОЙКИ.запись;
  for (const поле of п.цветныеПоля) {
    if (!п.цвет.test(String(з[поле]))) return false;
  }
  for (const поле of п.картинки) {
    if (з[поле] && !п.картинка.test(String(з[поле]))) return false;
  }
  if (!Number.isFinite(з.зерно)) return false;
  return true;
}
function показатьПоломку() {
  $('поломка').hidden = false;
  $('к-начать').hidden = true;
}
function перевести(запись) {
  const з = перевестиУстройство(запись);
  з.фигурыИзБиблиотеки = путиФигуры(з);
  return з;
}
function перевестиУстройство(запись) {
  const надо = НАСТРОЙКИ.хранение.версияЗаписи;
  if (запись.портрет && запись.источникПортрета !== НАСТРОЙКИ.портрет.источник) {
    запись.портретСтарый = true;
    запись.попыток = 0;
  }
  if ((запись.версия || 1) >= надо) return запись;
  if (запись.портрет) {
    запись.портретСтарый = true;
    запись.попыток = 0;
  }
  if (typeof запись.девиз === 'number') {
    const девизы = МИР.народы[запись.народ].девизы;
    const д = девизы[запись.девиз] || девизы[0];
    запись.девиз = д.ключ;
  }
  if (!запись.пол) {
    запись.пол = МИР.полы[(запись.зерно || 0) % МИР.полы.length].ключ;
  }
  if (!запись.цветКожи) {
    if (!запись.плащ) {
      запись.плащ = МИР.плащи[(запись.зерно || 0) % МИР.плащи.length].имя;
    }
    запись.цветПлаща = цветПлаща(запись);
    запись.цветКожи  = цветКожи(запись);
    запись.цветВолос = МИР.народы[запись.народ].волосы;
  }
  запись.версия = надо;
  return запись;
}
function снабдитьЛицом(з) {
  з.фигурыИзБиблиотеки = путиФигуры(з);
  return з;
}
function стереть() {
  try { localStorage.removeItem(НАСТРОЙКИ.хранение.ключ); } catch (е) {}
}
function девизГероя(з) {
  const девизы = МИР.народы[з.народ].девизы;
  return девизы.find((д) => д.ключ === з.девиз) || девизы[0];
}
function показатьГероя(з) {
  const н = МИР.народы[з.народ];
  применитьОттенок(з.народ);
  $('имя-героя').textContent = з.имя;
  $('род-героя').textContent = подставить(МИР.шаблоны.род,
    { народ: н.имя.toLowerCase(), земля: н.земля });
  $('судьба-героя').textContent = строкаСудьбы(з);
  $('девиз-героя').textContent = подставить(МИР.шаблоны.девиз,
    { девиз: девизГероя(з).текст });
  $('подпись-мира').textContent = МИР.подпись;
  показатьЭкран('э-герой');
  показатьПортрет(з);
}
function создатьГероя() {
  герой = {
    версия: НАСТРОЙКИ.хранение.версияЗаписи,
    имя: выбор.имя,
    народ: выбор.народ,
    пол: выбор.пол,
    телосложение: выбор.телосложение,
    цвет: выбор.цвет,
    отметина: выбор.отметина,
    плащ: выбор.плащ,
    цветПлаща: цветПлаща(выбор),
    цветКожи:  цветКожи(выбор),
    цветВолос: МИР.народы[выбор.народ].волосы,
    зерно: выбор.зерно,
    девиз: выбор.девиз,
    попыток: 0,
    портрет: null,
    источникПортрета: null,
    создан: new Date().toISOString()
  };
  снабдитьЛицом(герой);
  сохранить(герой);
  показатьГероя(герой);
  if (приГотовности) приГотовности();
}
function положитьПортрет(з, вышло) {
  if (!вышло.фигура) return false;
  з.портрет = вышло.фигура;
  з.источникПортрета = вышло.источник;
  з.портретСтарый = false;
  return true;
}
function перенос(кисть, текст, ширина) {
  const слова = текст.split(' ');
  const строки = [];
  let текущая = '';
  for (const слово of слова) {
    const проба = текущая ? текущая + ' ' + слово : слово;
    if (кисть.measureText(проба).width > ширина && текущая) {
      строки.push(текущая);
      текущая = слово;
    } else {
      текущая = проба;
    }
  }
  if (текущая) строки.push(текущая);
  return строки;
}
async function собратьКарточку(з) {
  const к = НАСТРОЙКИ.карточка;
  const холст = $('холст');
  холст.width = к.ширина;
  холст.height = к.высота;
  const кисть = холст.getContext('2d');
  const н = МИР.народы[з.народ];
  const поле = к.ширина * к.поле;
  const внутри = к.ширина - поле * 2;
  кисть.fillStyle = к.цвета.фон;
  кисть.fillRect(0, 0, к.ширина, к.высота);
  const сторона = к.ширина * к.портретДоля;
  const портретY = поле;
  let ширинаЛица = сторона, портретX = (к.ширина - сторона) / 2;
  const пути = з.портрет ? [з.портрет] : путиФигуры(з);
  let кадр = null;
  for (const адрес of пути) {
    кадр = await new Promise((готово) => {
      const и = new Image();
      и.onload = () => готово(и);
      и.onerror = () => готово(null);
      и.src = адрес;
    });
    if (кадр) break;
  }
  if (кадр) {
    ширинаЛица = сторона * кадр.naturalWidth / кадр.naturalHeight;
    портретX = (к.ширина - ширинаЛица) / 2;
    кисть.drawImage(кадр, портретX, портретY, ширинаЛица, сторона);
  } else {
    кисть.fillStyle = к.цвета.рамка;
    кисть.fillRect(портретX, портретY, ширинаЛица, сторона);
  }
  кисть.strokeStyle = н.оттенок;
  кисть.lineWidth = Math.max(1, к.ширина * к.толщинаРамки);
  кисть.strokeRect(портретX, портретY, ширинаЛица, сторона);
  let y = портретY + сторона + к.ширина * к.отступПослеПортрета;
  кисть.textAlign = 'center';
  const знакСторона = к.ширина * к.знакДоля;
  const знак = await знакКартинкой(з.народ, знакСторона);
  if (знак) кисть.drawImage(знак, (к.ширина - знакСторона) / 2, y, знакСторона, знакСторона);
  y += знакСторона + к.ширина * к.отступПослеЗнака;
  кисть.fillStyle = к.цвета.текст;
  кисть.font = к.жирностьИмени + ' ' + (к.ширина * к.кегльИмени) + 'px ' + к.шрифт;
  кисть.fillText(з.имя, к.ширина / 2, y);
  y += к.ширина * к.отступПослеИмени;
  кисть.fillStyle = н.оттенок;
  кисть.font = (к.ширина * к.кегльНарода) + 'px ' + к.шрифт;
  кисть.fillText(подставить(МИР.шаблоны.род,
    { народ: н.имя.toLowerCase(), земля: н.земля }), к.ширина / 2, y);
  y += к.ширина * к.отступПослеНарода;
  кисть.fillStyle = к.цвета.тусклый;
  кисть.font = (к.ширина * к.кегльСудьбы) + 'px ' + к.шрифт;
  for (const строка of перенос(кисть, строкаСудьбы(з), внутри)) {
    кисть.fillText(строка, к.ширина / 2, y);
    y += к.ширина * к.кегльСудьбы * к.межстрочный;
  }
  кисть.font = (к.ширина * к.кегльПодписи) + 'px ' + к.шрифт;
  кисть.fillStyle = к.цвета.тусклый;
  кисть.fillText(подставить(МИР.шаблоны.низКарточки,
    { подпись: МИР.подпись, призыв: МИР.тексты.карточка_призыв }),
    к.ширина / 2, к.высота - поле);
  return await new Promise((готово) => холст.toBlob(готово, 'image/png'));
}
function скачать(двоичное, имяФайла) {
  const адрес = URL.createObjectURL(двоичное);
  const ссылка = document.createElement('a');
  ссылка.href = адрес;
  ссылка.download = имяФайла;
  document.body.appendChild(ссылка);
  ссылка.click();
  ссылка.remove();
  setTimeout(() => URL.revokeObjectURL(адрес), НАСТРОЙКИ.портрет.ожиданиеМс);
}
async function показатьДрузьям() {
  $('к-показать').disabled = true;
  try {
    const двоичное = await собратьКарточку(герой);
    const файл = new File([двоичное], НАСТРОЙКИ.карточка.имяФайла, { type: 'image/png' });
    if (navigator.canShare && navigator.canShare({ files: [файл] })) {
      await navigator.share({ files: [файл] });
      $('сообщение').textContent = '';
    } else {
      скачать(двоичное, НАСТРОЙКИ.карточка.имяФайла);
      $('сообщение').textContent = МИР.тексты.поделиться_ошибка;
    }
  } catch (е) {
    $('сообщение').textContent = МИР.тексты.поделиться_ошибка;
  } finally {
    $('к-показать').disabled = false;
  }
}
function повеситьСобытия() {
  $('к-начать').addEventListener('click', () => {
    показатьЭкран('э-конструктор');
    перерисоватьВсё();
    показатьШаг(1);
  });
  document.querySelectorAll('[data-вперёд]').forEach((кн) =>
    кн.addEventListener('click', () => показатьШаг(Number(кн.dataset.вперёд))));
  document.querySelectorAll('[data-назад]').forEach((кн) =>
    кн.addEventListener('click', () => показатьШаг(Number(кн.dataset.назад))));
  document.querySelectorAll('[data-перемешать]').forEach((кн) =>
    кн.addEventListener('click', перемешать));
  $('народы').addEventListener('click', (с) => {
    const узел = с.target.closest('[data-народ]');
    if (узел) выбратьНарод(узел.dataset.народ);
  });
  $('шаг-2').addEventListener('click', (с) => {
    const у = с.target.closest(
      '[data-пол],[data-телосложение],[data-цвет],[data-отметина]');
    if (!у) return;
    if (у.dataset.пол) выбор.пол = у.dataset.пол;
    if (у.dataset.телосложение) выбор.телосложение = у.dataset.телосложение;
    if (у.dataset.цвет) выбор.цвет = у.dataset.цвет;
    if (у.dataset.отметина) выбор.отметина = у.dataset.отметина;
    нарисоватьОблик();
    обновитьПревью();
  });
  $('поле-имя').addEventListener('input', проверитьИмя);
  $('к-подтвердить').addEventListener('click', создатьГероя);
  $('к-показать').addEventListener('click', показатьДрузьям);
  $('к-портрет').addEventListener('click', догнатьПортрет);
  $('к-починить').addEventListener('click', () => location.reload());
  $('к-сначала').addEventListener('click', () => {
    if (!confirm(МИР.тексты.поломка_вопрос)) return;
    стереть();
    поломка = false;
    $('поломка').hidden = true;
    $('к-начать').hidden = false;
  });
  $('к-заново').addEventListener('click', () => {
    if (!confirm(МИР.тексты.заново_вопрос)) return;
    стереть();
    герой = null;
    выбор = случайныйВыбор();
    $('поле-имя').value = '';
    $('сообщение').textContent = '';
    показатьЭкран('э-вступление');
  });
}
function запуск() {
  расставитьТексты();
  $('полоска').innerHTML = '<i></i>'.repeat(НАСТРОЙКИ.шагов);
  $('поле-имя').maxLength = НАСТРОЙКИ.имя.макс;
  $('поле-имя').placeholder = МИР.тексты.поле_имя;
  выбор = случайныйВыбор();
  повеситьСобытия();
  const прочитано = достать();
  герой = прочитано.запись || null;
  поломка = Boolean(прочитано.поломка);
  if (поломка) показатьПоломку();
  else if (герой) обновитьСтарыйПортрет();
}
let приГотовности = null;
return {
  запуск: запуск,
  показать: function () {
    if (герой) показатьГероя(герой);
    else показатьЭкран('э-вступление');
  },
  есть:  () => Boolean(герой),
  поломка: () => поломка,
  запись: () => герой,
  когдаГотов: function (что) { приГотовности = что; },
  вМир: function () { if (приГотовности) приГотовности(); }
};
})();
